export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const t = time;
  const height = launchSpeed * t - 0.5 * gravity * t * t;
  const velocity = launchSpeed - gravity * t;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const clampedH = Math.max(0, height);
  const scaleY = 300 / 2.5;
  const baseY = 360;
  const ballY = baseY - clampedH * scaleY;
  const ballX = 320;

  const objects = [];
  objects.push(sdk.panel({ x: 40, y: 40, w: 560, h: 360, title: "Vertical Toss", state: t < apexTime ? "Moving up" : (Math.abs(velocity) < 0.1 ? "Still for an instant" : "Moving down"), id: "lane.toss" }));
  objects.push(sdk.axis("axis.height", { x: 100, y: 360, length: 300, orientation: "y", min: 0, max: 2.5, ticks: [0, 0.5, 1.0, 1.5, 2.0, 2.5], label: "Height", unit: "m" }));
  objects.push(sdk.groundMark("ground.launch", ballX, baseY, 60, "Launch"));

  if (height >= 0) {
    objects.push(sdk.circle("ball.toss", ballX, ballY, 24, { role: "output" }));
  }

  if (Math.abs(velocity) > 0.05) {
    objects.push(sdk.vector("vec.v", { x: ballX, y: ballY }, { value: velocity, direction: "up" }, { scale: 15, minLength: 12, label: "v", role: "output" }));
  }

  objects.push(sdk.vector("vec.a", { x: ballX + 25, y: ballY }, { value: -gravity, direction: "up" }, { scale: 5, minLength: 12, label: "a", role: "observed" }));

  let motionStateText = "Moving up";
  if (Math.abs(velocity) < 0.05) {
    motionStateText = "Still for an instant";
  } else if (velocity < 0) {
    motionStateText = "Moving down";
  }

  const calloutLines = [
    motionStateText,
    "Gravity pulls down"
  ];
  objects.push(sdk.callout(ballX + 45, ballY - 20, calloutLines, { id: "callout.toss" }));

  const motionStateVal = motionStateText;
  const gravityStateVal = "Gravity pulls down";

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionStateVal },
        { id: "gravityState", value: gravityStateVal }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      velocity,
      height
    }
  };
}
